static bool command_freed;
static bool response_sent;

LOG_MODULE_DECLARE(rpc_server, CONFIG_INFUSE_RPC_LOG_LEVEL);

void rpc_command_runner_request_unref(struct net_buf *request)
{
	net_buf_unref(request);
	command_freed = true;
}

void rpc_command_runner_early_response(struct epacket_rx_metadata *rx_meta, uint32_t request_id,
				       uint16_t command_id, struct net_buf *response)
{
	struct infuse_rpc_rsp_header *rsp_header;

	rsp_header = (void *)response->data;
	rsp_header->request_id = request_id;
	rsp_header->command_id = command_id;

	/* Metadata and core response info */
	epacket_set_tx_metadata_core(response, rx_meta->auth, rx_meta->key_identifier, 0x00,
				     INFUSE_RPC_RSP, rx_meta->interface_address);

	/* Push response back over incoming interface */
	epacket_queue(rx_meta->interface, response);
	response_sent = true;
}

void rpc_command_runner(struct net_buf *request)
{
	struct epacket_rx_metadata *metadata = net_buf_user_data(request);
	const struct device *interface = metadata->interface;
	union epacket_interface_address from = metadata->interface_address;
	struct infuse_rpc_req_header *req_header = (void *)request->data;
	struct infuse_rpc_rsp_header *rsp_header;
	struct net_buf *response = NULL;
	enum epacket_auth auth = metadata->auth;
	uint32_t key_id = metadata->key_identifier;
	uint32_t request_id = 0;
	uint16_t command_id = 0;
	int16_t rc = INFUSE_RPC_ERROR_INVALID_COMMAND;

	/* Reset command freed state */
	command_freed = false;
	response_sent = false;

	if (request->len < sizeof(*req_header)) {
		rc = INFUSE_RPC_ERROR_MALFORMED_REQUEST;
		goto respond;
	}
	request_id = req_header->request_id;
	command_id = req_header->command_id;

	LOG_DBG("Handling RPC: %d Auth: %d", command_id, auth);

	for (size_t i = 0; i < ARRAY_SIZE(command_impls); i++) {
		const struct command_impl *impl = &command_impls[i];

		if (impl->command_id != command_id) {
			continue;
		}
		if (auth < impl->required_auth) { /* GCOVR_EXCL_BR_LINE */
			rc = INFUSE_RPC_ERROR_AUTHENTICATION_REQUIRED;
			goto respond;
		}
		if (request->len < impl->request_len) {
			rc = INFUSE_RPC_ERROR_MALFORMED_REQUEST;
			goto respond;
		}
		response = impl->handler(request);
		break;
	}

respond:
	/* Free the request */
	if (!command_freed) {
		net_buf_unref(request);
	}
	if (response_sent) {
		/* Response already run */
		__ASSERT_NO_MSG(response == NULL);
		return;
	}

	if (response == NULL) {
		/* No command run, alloc the response packet */
		response = epacket_alloc_tx_for_interface(interface, K_FOREVER);
		if (net_buf_tailroom(response) == 0) {
			/* Response channel closed */
			net_buf_unref(response);
			return;
		}
		rsp_header = net_buf_add(response, sizeof(*rsp_header));
		rsp_header->return_code = rc;
	} else {
		rsp_header = (void *)response->data;
	}
	rsp_header->request_id = request_id;
	rsp_header->command_id = command_id;

	/* Metadata and core response info */
	epacket_set_tx_metadata_core(response, auth, key_id, 0x00, INFUSE_RPC_RSP, from);

	/* Push response back over incoming interface */
	epacket_queue(interface, response);
}
